<?php use App\Core\Security;require BASE_PATH.'/app/Views/layout/header.php';?><div class="d-flex justify-content-between mb-3"><div><h2>Book reservations</h2><p class="text-muted">Track requests for books before check-out.</p></div><a class="btn btn-pink" href="<?= BASE_URL ?>/?page=reservations&action=create">+ New reservation</a></div><div class="card p-3"><table class="table"><thead><tr><th>Book</th><th>Requester</th><th>ID</th><th>Contact</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= Security::e($r['title']) ?></td><td><?= Security::e($r['requester_name']) ?></td><td><?= Security::e($r['requester_id']) ?></td><td><?= Security::e($r['contact']) ?></td><td><?= Security::e(ucfirst($r['status'])) ?></td><td><div class="d-flex gap-1"><form method="post" action="<?= BASE_URL ?>/?page=reservations&action=status" class="d-flex gap-1"><input type="hidden" name="_csrf" value="<?= Security::csrf() ?>"><input type="hidden" name="id" value="<?= $r['id'] ?>"><select name="status" class="form-select form-select-sm"><option value="pending">Pending</option><option value="fulfilled">Fulfilled</option><option value="cancelled">Cancelled</option></select><button class="btn btn-sm btn-outline-dark">Save</button></form><?php if($r['status']!=='fulfilled'):?><form method="post" action="<?= BASE_URL ?>/?page=reservations&action=delete" onsubmit="return confirm('Delete this reservation?');"><input type="hidden" name="_csrf" value="<?= Security::csrf() ?>"><input type="hidden" name="id" value="<?= $r['id'] ?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';?>
